import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { PlaneGeometry, Group, Mesh } from 'three/webgpu';
import { uv, vec2, texture, uniform, mix, smoothstep, time, screenUV } from 'three/tsl';

export default function createNode(config, ctx) {
  const { paper, surface } = config.colors || { paper: '#e8ecf2', surface: '#0b0b10' };

  // --- Gather text content ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find(item => item.role === 'headline') || items[0] || { text: 'Journal 1', fontSize: 39 };

  // --- Build group ---
  const group = new Group();

  // --- Plane geometry & material ---
  const aspectRatio = 512 / 320; // ~1.6
  const width = 1.6;
  const height = width / aspectRatio; // 1.0
  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    color: surface,
    roughness: 0.6,
    metalness: 0.3,
  });

  // Load texture asynchronously
  let textureMap = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then(tex => {
      tex.colorSpace = 'srgb';
      tex.anisotropy = 4;
      material.map = tex;
      material.needsUpdate = true;
      textureMap = tex;
    }).catch(() => {
      // fallback: keep surface color
    });
  }

  const plane = new Mesh(geometry, material);
  group.add(plane);

  // --- Text overlay ---
  const fontSize = headlineItem.fontSize || 39;
  const textOpts = {
    fontSize: fontSize,
    color: paper,
    align: 'center',
    maxWidthPx: width * 200, // approximate pixel width (scene units * 200 PPI)
    letterSpacingPx: 2,
  };
  const textObj = ctx.fontAtlas.createText(String(headlineItem.text), textOpts);
  textObj.position.set(0, 0, 0.01); // slight z offset
  // Scale text to fit plane width (approximate)
  const textScale = width / 1.6; // plane width is 1.6, text is designed for ~1.6 unit width
  textObj.scale.set(textScale, textScale, 1);
  group.add(textObj);

  // --- State for cleanup ---
  const cleanupRefs = {
    geometry,
    material,
    textureMap,
    textObj,
    timelines: [],
  };

  // --- Handlers (none) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Kill GSAP timelines
    cleanupRefs.timelines.forEach(timeline => timeline.kill());
    // Dispose geometry
    cleanupRefs.geometry.dispose();
    // Dispose material
    cleanupRefs.material.dispose();
    // Dispose texture if loaded
    if (cleanupRefs.textureMap) {
      cleanupRefs.textureMap.dispose();
    }
    // Remove text object from scene (if still attached)
    if (cleanupRefs.textObj.parent) {
      cleanupRefs.textObj.parent.remove(cleanupRefs.textObj);
    }
  };

  return group;
}
